const ALLOWED_HEADERS = 'authorization, x-client-info, apikey, content-type';
const ALLOWED_METHODS = 'GET, POST, PUT, PATCH, DELETE, OPTIONS';

function parseAllowedOrigins(): Set<string> {
  const raw = Deno.env.get('ALLOWED_ORIGINS') ?? '';
  return new Set(
    raw
      .split(',')
      .map((origin) => origin.trim())
      .filter(Boolean),
  );
}

let cachedOrigins: Set<string> | null = null;

function getAllowedOrigins(): Set<string> {
  if (!cachedOrigins) {
    cachedOrigins = parseAllowedOrigins();
  }
  return cachedOrigins;
}

/** Origin-aware CORS headers. Set ALLOWED_ORIGINS (comma-separated) in env. */
export function getCorsHeaders(req: Request): Record<string, string> {
  const headers: Record<string, string> = {
    'Access-Control-Allow-Headers': ALLOWED_HEADERS,
    'Access-Control-Allow-Methods': ALLOWED_METHODS,
  };

  const origin = req.headers.get('Origin');
  if (origin && getAllowedOrigins().has(origin)) {
    headers['Access-Control-Allow-Origin'] = origin;
    headers['Vary'] = 'Origin';
  }

  return headers;
}

/**
 * Parse booking time slots stored as 24h (HH:mm / HH:mm:ss) or 12h (h:mm a).
 */
export function parseBookingTimeToDate(timeString: string): Date | null {
  if (!timeString || typeof timeString !== "string") return null;
  const trimmed = timeString.trim();
  if (!trimmed) return null;

  const ref = new Date(2000, 0, 1);

  const try24WithSeconds = /^(\d{1,2}):(\d{2}):(\d{2})$/.exec(trimmed);
  if (try24WithSeconds) {
    const d = new Date(ref);
    d.setHours(parseInt(try24WithSeconds[1], 10), parseInt(try24WithSeconds[2], 10), 0, 0);
    return d;
  }

  const try24 = /^(\d{1,2}):(\d{2})$/.exec(trimmed);
  if (try24 && !/\s*(AM|PM)/i.test(trimmed)) {
    const d = new Date(ref);
    d.setHours(parseInt(try24[1], 10), parseInt(try24[2], 10), 0, 0);
    return d;
  }

  const try12 = /^(\d{1,2}):(\d{2})\s*(AM|PM)$/i.exec(trimmed);
  if (try12) {
    let hours = parseInt(try12[1], 10);
    const minutes = parseInt(try12[2], 10);
    const meridiem = try12[3].toUpperCase();
    if (meridiem === "PM" && hours < 12) hours += 12;
    if (meridiem === "AM" && hours === 12) hours = 0;
    const d = new Date(ref);
    d.setHours(hours, minutes, 0, 0);
    return d;
  }

  return null;
}

function formatClock(date: Date): string {
  return date.toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
  });
}

function parseDeliveryWindow(timeString: string): { start: Date; end: Date } | null {
  if (!timeString || typeof timeString !== "string") return null;
  const trimmed = timeString.trim();
  if (!trimmed) return null;

  if (trimmed.includes("|")) {
    const [startRaw, endRaw] = trimmed.split("|").map((t) => t.trim()).filter(Boolean);
    const start = parseBookingTimeToDate(startRaw);
    const end = parseBookingTimeToDate(endRaw);
    if (start && end) return { start, end };
    if (start) {
      const endFallback = new Date(start);
      endFallback.setHours(endFallback.getHours() + 2);
      return { start, end: endFallback };
    }
    return null;
  }

  const start = parseBookingTimeToDate(trimmed);
  if (!start) return null;
  const end = new Date(start);
  end.setHours(end.getHours() + 2);
  return { start, end };
}

export function formatBookingTime(
  timeString: string,
  options: { isSelfService?: boolean; isReturnBy?: boolean } = {},
): string {
  if (!timeString) return "N/A";

  if (typeof timeString === "string" && timeString.includes("|")) {
    const window = parseDeliveryWindow(timeString);
    if (window) return `${formatClock(window.start)} - ${formatClock(window.end)}`;
  }

  const parsed = parseBookingTimeToDate(timeString);
  if (!parsed) return timeString;

  const formatted = formatClock(parsed);

  if (options.isSelfService) {
    const hour24 = parsed.getHours();
    const minute = parsed.getMinutes();
    if (options.isReturnBy || hour24 >= 22 || (hour24 === 23 && minute === 0)) {
      return `by ${formatted}`;
    }
    if (hour24 <= 8 || (hour24 === 6 && minute === 0)) {
      return `after ${formatted}`;
    }
  }

  return formatted;
}

/** Delivery copy: "between 6:00 AM and 8:00 AM" (pipe range or 2-hour window from start). */
export function formatDeliveryTimeWindowBetween(timeString: string): string {
  const window = parseDeliveryWindow(timeString);
  if (!window) return timeString || "N/A";
  return `between ${formatClock(window.start)} and ${formatClock(window.end)}`;
}

/** 12-hour time only (no "after" / "by" prefix) for copy that already includes those words. */
export function formatPlainBookingTime(timeString: string): string {
  if (!timeString) return "N/A";
  if (typeof timeString === "string" && timeString.includes("|")) {
    const window = parseDeliveryWindow(timeString);
    if (window) return `${formatClock(window.start)} - ${formatClock(window.end)}`;
  }
  const parsed = parseBookingTimeToDate(timeString);
  if (!parsed) return timeString;
  return formatClock(parsed);
}

const DEFAULT_SITE_URL = "https://u-filldumpsters.com";

/** Resolve app origin for links in emails (request body → SITE_URL env → production default). */
export function normalizeSiteUrl(url?: string | null): string {
  const fallback = Deno.env.get("SITE_URL") || DEFAULT_SITE_URL;
  const candidate = url && url.trim().length > 0 ? url : fallback;

  try {
    const parsed = new URL(candidate);
    return `${parsed.origin}`.replace(/\/$/, "");
  } catch {
    return DEFAULT_SITE_URL;
  }
}

/**
 * Hostnames that work inside the Supabase Docker network but not in a customer's browser.
 * Never put these into email links.
 */
function isInternalSupabaseHostname(hostname: string): boolean {
  const host = hostname.toLowerCase();
  return (
    host === "kong" ||
    host === "host.docker.internal" ||
    host.endsWith(".internal") ||
    host.endsWith(".local")
  );
}

/**
 * Public base for edge-function links used in outbound emails.
 * Prefer an explicit public URL; never emit docker-internal SUPABASE_URL (e.g. http://kong:8000).
 */
export function resolvePublicFunctionsBaseUrl(siteUrl?: string | null): string {
  const site = normalizeSiteUrl(siteUrl);

  const explicit =
    Deno.env.get("PUBLIC_SUPABASE_URL") ||
    Deno.env.get("PUBLIC_FUNCTIONS_URL") ||
    Deno.env.get("SITE_SUPABASE_URL");

  if (explicit && explicit.trim()) {
    const cleaned = explicit
      .trim()
      .replace(/\/+$/, "")
      .replace(/\/functions\/v1$/i, "");
    return `${cleaned}/functions/v1`;
  }

  const supabaseUrl = (Deno.env.get("SUPABASE_URL") || "").trim();
  if (supabaseUrl) {
    try {
      const parsed = new URL(supabaseUrl);
      if (!isInternalSupabaseHostname(parsed.hostname)) {
        return `${parsed.origin.replace(/\/$/, "")}/functions/v1`;
      }
    } catch {
      // fall through to site origin
    }
  }

  // Local docker injects http://kong:8000 — use the app origin (Vite proxies /functions/v1).
  return `${site}/functions/v1`;
}

/** Build a browser-reachable unsubscribe link for early-leave emails. */
export function buildUnsubscribeUrl(
  token: string | null | undefined,
  siteUrl?: string | null,
): string | null {
  if (!token) return null;
  const base = resolvePublicFunctionsBaseUrl(siteUrl);
  return `${base}/unsubscribe?token=${encodeURIComponent(String(token))}`;
}

/**
 * Shared Brevo / Resend email + Brevo / Twilio SMS helpers.
 * SMS_PROVIDER env: "brevo" (default) | "twilio"
 */

const BREVO_API_KEY = Deno.env.get("BREVO_API_KEY");
const BREVO_FROM_EMAIL = Deno.env.get("BREVO_FROM_EMAIL") || "noreply@u-filldumpsters.com";
const BREVO_SMS_SENDER = Deno.env.get("BREVO_SMS_SENDER") || "UFillDump";
const RESEND_API_KEY = Deno.env.get("RESEND_API_KEY");
const SMS_PROVIDER = (Deno.env.get("SMS_PROVIDER") || "brevo").toLowerCase();
const TWILIO_ACCOUNT_SID = Deno.env.get("TWILIO_ACCOUNT_SID");
const TWILIO_AUTH_TOKEN = Deno.env.get("TWILIO_AUTH_TOKEN");
const TWILIO_FROM_NUMBER = Deno.env.get("TWILIO_FROM_NUMBER");

export type SendEmailResult = {
  success: boolean;
  provider?: string;
  error?: string;
  result?: unknown;
  /** Provider message id when available (Brevo messageId / Resend id). */
  messageId?: string;
};

export type SendSmsResult = {
  success: boolean;
  provider?: string;
  skipped?: boolean;
  reason?: string;
  error?: string;
  result?: unknown;
};

/** Normalize to E.164-ish digits; assume US (+1) when 10 digits. */
export function normalizePhoneE164(phone: string | null | undefined): string | null {
  if (!phone) return null;
  const digits = phone.replace(/\D/g, "");
  if (digits.length === 10) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith("1")) return `+${digits}`;
  if (phone.trim().startsWith("+") && digits.length >= 10) return `+${digits}`;
  return null;
}

export async function sendEmail(
  toEmail: string,
  subject: string,
  htmlContent: string,
  maxRetries = 4,
): Promise<SendEmailResult> {
  let lastError: string | null = null;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const ts = new Date().toISOString();
    try {
      if (BREVO_API_KEY) {
        const brevoResponse = await fetch("https://api.brevo.com/v3/smtp/email", {
          method: "POST",
          headers: {
            "api-key": BREVO_API_KEY,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            sender: { email: BREVO_FROM_EMAIL, name: "U-Fill Dumpsters" },
            to: [{ email: toEmail }],
            subject,
            htmlContent,
          }),
        });
        if (brevoResponse.ok) {
          const result = await brevoResponse.json();
          const messageId =
            typeof result?.messageId === "string"
              ? result.messageId
              : typeof result?.messageIds?.[0] === "string"
              ? result.messageIds[0]
              : undefined;
          console.log(
            `[${ts}] [notify] Brevo accepted email to=${toEmail} from=${BREVO_FROM_EMAIL} messageId=${messageId || "unknown"}`,
          );
          return { success: true, provider: "brevo", result, messageId };
        }
        lastError = `Brevo API error: ${await brevoResponse.text()}`;
        console.error(`[${ts}] [notify] Brevo email failed:`, lastError);
      }

      if (RESEND_API_KEY) {
        const resendResponse = await fetch("https://api.resend.com/emails", {
          method: "POST",
          headers: {
            Authorization: `Bearer ${RESEND_API_KEY}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            from: "U-Fill Dumpsters <noreply@u-filldumpsters.com>",
            to: [toEmail],
            subject,
            html: htmlContent,
          }),
        });
        if (resendResponse.ok) {
          const result = await resendResponse.json();
          const messageId = typeof result?.id === "string" ? result.id : undefined;
          console.log(
            `[${ts}] [notify] Resend accepted email to=${toEmail} messageId=${messageId || "unknown"}`,
          );
          return { success: true, provider: "resend", result, messageId };
        }
        lastError = `Resend API error: ${await resendResponse.text()}`;
        console.error(`[${ts}] [notify] Resend email failed:`, lastError);
      }

      if (!BREVO_API_KEY && !RESEND_API_KEY) {
        return { success: false, error: "No email service configured" };
      }

      if (attempt < maxRetries) {
        await new Promise((r) => setTimeout(r, Math.pow(2, attempt) * 1000));
      }
    } catch (err) {
      lastError = err instanceof Error ? err.message : String(err);
      console.error(`[${ts}] [notify] Email exception:`, lastError);
      if (attempt < maxRetries) {
        await new Promise((r) => setTimeout(r, Math.pow(2, attempt) * 1000));
      }
    }
  }
  return { success: false, error: lastError || "Unknown email error" };
}

async function sendSmsBrevo(toE164: string, content: string): Promise<SendSmsResult> {
  if (!BREVO_API_KEY) {
    return { success: false, error: "BREVO_API_KEY not configured" };
  }
  const res = await fetch("https://api.brevo.com/v3/transactionalSMS/sms", {
    method: "POST",
    headers: {
      "api-key": BREVO_API_KEY,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      sender: BREVO_SMS_SENDER.slice(0, 11),
      recipient: toE164,
      content,
      type: "transactional",
    }),
  });
  if (!res.ok) {
    return { success: false, provider: "brevo", error: await res.text() };
  }
  return { success: true, provider: "brevo", result: await res.json() };
}

async function sendSmsTwilio(toE164: string, content: string): Promise<SendSmsResult> {
  if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN || !TWILIO_FROM_NUMBER) {
    return { success: false, error: "Twilio env vars not configured" };
  }
  const auth = btoa(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`);
  const body = new URLSearchParams({
    To: toE164,
    From: TWILIO_FROM_NUMBER,
    Body: content,
  });
  const res = await fetch(
    `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Messages.json`,
    {
      method: "POST",
      headers: {
        Authorization: `Basic ${auth}`,
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body,
    },
  );
  if (!res.ok) {
    return { success: false, provider: "twilio", error: await res.text() };
  }
  return { success: true, provider: "twilio", result: await res.json() };
}

/**
 * Send an SMS. Skips when phone is missing or customer has opted out.
 * @param smsOptIn - when false, skip; when undefined/true, send
 */
export async function sendSms(
  phone: string | null | undefined,
  content: string,
  options: { smsOptIn?: boolean | null } = {},
): Promise<SendSmsResult> {
  if (options.smsOptIn === false) {
    return { success: true, skipped: true, reason: "sms_opt_out" };
  }
  const toE164 = normalizePhoneE164(phone);
  if (!toE164) {
    return { success: true, skipped: true, reason: "invalid_phone" };
  }

  try {
    if (SMS_PROVIDER === "twilio") {
      return await sendSmsTwilio(toE164, content);
    }
    return await sendSmsBrevo(toE164, content);
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/**
 * send-abandoned-checkout-reminder
 *
 * Finds pending_payment bookings between 1h and 2h old that have not been
 * reminded yet, sends a professional finish-your-order email, stamps
 * addons.abandoned_reminder_sent_at, and upserts abandoned_checkouts.
 */

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.45.4";
import { getCorsHeaders } from "./cors.ts";
import { sendEmail } from "../_shared/notify.ts";
import { normalizeSiteUrl } from "../_shared/normalizeSiteUrl.ts";
import { formatCustomerFacingPlanName } from "../_shared/displayPlanName.ts";
import { formatBookingTime, parseBookingTimeToDate } from "../_shared/formatBookingTime.ts";

function jsonResponse(corsHeaders: Record<string, string>, body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

function formatDate(value: string | null | undefined): string {
  if (!value) return "N/A";
  try {
    const d = new Date(`${value}T12:00:00`);
    return d.toLocaleDateString("en-US", {
      weekday: "short",
      month: "short",
      day: "numeric",
      year: "numeric",
    });
  } catch {
    return String(value);
  }
}

function formatTimeSlot(raw: string | null | undefined): string {
  if (!raw) return "N/A";
  const s = String(raw);
  if (s.includes("|")) {
    const [start, end] = s.split("|").map((t) => t.trim());
    const a = parseBookingTimeToDate(start);
    const b = parseBookingTimeToDate(end);
    if (a && b) {
      const fmt = (d: Date) =>
        d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit", hour12: true });
      return `${fmt(a)} - ${fmt(b)}`;
    }
  }
  return formatBookingTime(s);
}

function money(amount: unknown): string {
  const n = Number(amount);
  if (!Number.isFinite(n)) return "$0.00";
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(n);
}

function benefitCopy(serviceName: string, plan: Record<string, unknown>, addons: Record<string, unknown>): string {
  const name = (serviceName || "").toLowerCase();
  const isDelivery = Boolean(addons?.isDelivery || addons?.deliveryService || name.includes("delivery"));
  const planId = Number(plan?.id);

  if (planId === 2 || name.includes("dump trailer") || name.includes("dumpster")) {
    if (isDelivery) {
      return "Your Dump Trailer with Delivery is reserved in our system—convenient drop-off and pickup so you can focus on the job, not the logistics.";
    }
    return "Your dump trailer rental is almost ready. Finish checkout to lock in your dates and get clear pickup instructions.";
  }
  if (planId === 1 || name.includes("compact") || name.includes("equipment")) {
    return "The compact equipment you selected is still available on your hold. Complete payment to secure it for your project timeline.";
  }
  if (name.includes("rock") || name.includes("mulch") || name.includes("gravel") || name.includes("material")) {
    return "Your material delivery selection is saved. Finish checkout so we can schedule delivery for the dates you chose.";
  }
  return "Your rental details are saved and waiting. Completing checkout takes just a minute and keeps your preferred schedule.";
}

function equipmentListHtml(addons: Record<string, unknown>): string {
  const equipment = Array.isArray(addons?.equipment) ? addons.equipment : [];
  if (equipment.length === 0) return "";
  const items = equipment
    .map((item: Record<string, unknown>) => {
      const label = String(item.name || item.label || item.id || "Equipment");
      const qty = Number(item.quantity || 1);
      return `<li style="padding:6px 0;border-bottom:1px solid #e5e7eb;">${label} × ${qty}</li>`;
    })
    .join("");
  return `
    <div style="margin-top:18px;">
      <h3 style="margin:0 0 8px;color:#1e3a8a;font-size:16px;">Selected add-ons</h3>
      <ul style="list-style:none;padding:0;margin:0;">${items}</ul>
    </div>`;
}

function protectionListHtml(addons: Record<string, unknown>, plan: Record<string, unknown>): string {
  const bits: string[] = [];
  if (addons?.insurance === "accept") bits.push("Rental Insurance");
  if (Number(plan?.id) === 1 && addons?.drivewayProtection === "accept") bits.push("Driveway Protection");
  if (bits.length === 0) return "";
  return `<p style="margin:12px 0 0;color:#374151;font-size:14px;"><strong>Protection:</strong> ${bits.join(" · ")}</p>`;
}

function buildReminderHtml(booking: Record<string, unknown>, siteUrl: string): string {
  const plan = (booking.plan || {}) as Record<string, unknown>;
  const addons = (booking.addons || {}) as Record<string, unknown>;
  const serviceName = formatCustomerFacingPlanName(plan.name || "Your rental");
  const firstName = String(booking.first_name || "").trim() ||
    String(booking.name || "there").trim().split(/\s+/)[0] ||
    "there";
  const total = money(booking.total_price);
  const dropOff = `${formatDate(String(booking.drop_off_date || ""))} · ${formatTimeSlot(String(booking.drop_off_time_slot || ""))}`;
  const pickUp = `${formatDate(String(booking.pickup_date || ""))} · ${formatTimeSlot(String(booking.pickup_time_slot || ""))}`;
  const ctaUrl = `${siteUrl}/`;
  const benefit = benefitCopy(serviceName, plan, addons);

  return `<!DOCTYPE html>
<html>
<head><meta charset="utf-8" /><meta name="viewport" content="width=device-width, initial-scale=1" /></head>
<body style="margin:0;padding:0;background:#0f172a;font-family:Arial,Helvetica,sans-serif;">
  <div style="max-width:640px;margin:0 auto;padding:24px 16px;">
    <div style="background:#111827;border:1px solid #334155;border-radius:16px;overflow:hidden;">
      <div style="background:linear-gradient(135deg,#1e3a8a,#0f172a);padding:28px 24px;text-align:center;">
        <p style="margin:0;color:#fbbf24;font-size:12px;letter-spacing:1.5px;text-transform:uppercase;font-weight:700;">U-Fill Dumpsters</p>
        <h1 style="margin:10px 0 0;color:#ffffff;font-size:24px;line-height:1.3;">Your rental is waiting</h1>
      </div>
      <div style="padding:28px 24px;background:#ffffff;color:#111827;">
        <p style="margin:0 0 14px;font-size:16px;">Hi ${firstName},</p>
        <p style="margin:0 0 14px;font-size:15px;line-height:1.55;color:#374151;">
          You started a booking with us and left before payment was completed. We saved your details so you can finish whenever you are ready.
        </p>
        <p style="margin:0 0 18px;font-size:15px;line-height:1.55;color:#374151;">${benefit}</p>

        <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px;padding:16px 18px;">
          <p style="margin:0 0 8px;color:#1e3a8a;font-weight:700;font-size:15px;">${serviceName}</p>
          <p style="margin:0;color:#475569;font-size:14px;line-height:1.5;"><strong>Start:</strong> ${dropOff}</p>
          <p style="margin:6px 0 0;color:#475569;font-size:14px;line-height:1.5;"><strong>End:</strong> ${pickUp}</p>
          <p style="margin:12px 0 0;color:#0f172a;font-size:18px;font-weight:700;">Total: ${total}</p>
          ${protectionListHtml(addons, plan)}
          ${equipmentListHtml(addons)}
        </div>

        <div style="text-align:center;margin:28px 0 10px;">
          <a href="${ctaUrl}" style="display:inline-block;background:#eab308;color:#111827;text-decoration:none;font-weight:700;padding:14px 28px;border-radius:10px;font-size:15px;">
            Finish your booking
          </a>
        </div>
        <p style="margin:0;font-size:13px;line-height:1.5;color:#64748b;text-align:center;">
          Prefer to start fresh? Visit our site, choose the same service, and we will help you get scheduled.
        </p>
      </div>
      <div style="padding:18px 24px;background:#0f172a;text-align:center;">
        <p style="margin:0;color:#94a3b8;font-size:12px;line-height:1.5;">
          You fill it, we dump it — convenience brought to you.<br/>
          Questions? Reply to this email or visit <a href="${siteUrl}" style="color:#fbbf24;text-decoration:none;">u-filldumpsters.com</a>
        </p>
      </div>
    </div>
  </div>
</body>
</html>`;
}

Deno.serve(async (req) => {
  const corsHeaders = getCorsHeaders(req);
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
  );

  try {
    const siteUrl = normalizeSiteUrl();
    const now = Date.now();
    const oneHourAgo = new Date(now - 60 * 60 * 1000).toISOString();
    const twoHoursAgo = new Date(now - 2 * 60 * 60 * 1000).toISOString();

    const { data: bookings, error } = await supabase
      .from("bookings")
      .select(
        "id, email, phone, name, first_name, last_name, status, plan, addons, total_price, drop_off_date, pickup_date, drop_off_time_slot, pickup_time_slot, contact_address, delivery_address, created_at",
      )
      .eq("status", "pending_payment")
      .lt("created_at", oneHourAgo)
      .gte("created_at", twoHoursAgo)
      .order("created_at", { ascending: true })
      .limit(100);

    if (error) throw error;

    const candidates = (bookings || []).filter((b) => {
      const addons = (b.addons || {}) as Record<string, unknown>;
      return !addons.abandoned_reminder_sent_at;
    });

    let sent = 0;
    let skipped = 0;
    const errors: Array<{ bookingId: number; error: string }> = [];

    for (const booking of candidates) {
      const email = String(booking.email || "").trim();
      if (!email) {
        skipped += 1;
        continue;
      }

      // Skip if already filed as intentional leave-early (cancelled + CRM lead)
      const { data: existingLead } = await supabase
        .from("abandoned_checkouts")
        .select("id, status")
        .eq("booking_id", booking.id)
        .maybeSingle();

      if (existingLead?.status === "left_early") {
        skipped += 1;
        continue;
      }

      const plan = (booking.plan || {}) as Record<string, unknown>;
      const serviceName = formatCustomerFacingPlanName(plan.name || "your rental");
      const html = buildReminderHtml(booking as Record<string, unknown>, siteUrl);
      const subject = `Still interested? Finish your ${serviceName} booking`;

      const emailResult = await sendEmail(email, subject, html);
      if (!emailResult.success) {
        errors.push({ bookingId: booking.id, error: emailResult.error || "send failed" });
        continue;
      }

      const nextAddons = {
        ...((booking.addons || {}) as Record<string, unknown>),
        abandoned_reminder_sent_at: new Date().toISOString(),
      };

      const { error: stampError } = await supabase
        .from("bookings")
        .update({ addons: nextAddons })
        .eq("id", booking.id)
        .eq("status", "pending_payment");

      if (stampError) {
        errors.push({ bookingId: booking.id, error: stampError.message });
      }

      const { error: upsertError } = await supabase.rpc("upsert_abandoned_checkout_from_booking", {
        p_booking_id: booking.id,
        p_status: "reminded",
        p_set_reminder_sent: true,
      });

      if (upsertError) {
        console.error("[send-abandoned-checkout-reminder] upsert failed:", upsertError);
        errors.push({ bookingId: booking.id, error: upsertError.message });
      }

      sent += 1;
    }

    return jsonResponse(corsHeaders, {
      ok: true,
      scanned: bookings?.length || 0,
      candidates: candidates.length,
      sent,
      skipped,
      errors,
    });
  } catch (err) {
    console.error("[send-abandoned-checkout-reminder] CRITICAL:", err);
    return jsonResponse(
      corsHeaders,
      { ok: false, error: err instanceof Error ? err.message : String(err) },
      500,
    );
  }
});
